// Sıralama yarışının saf mantığı: ara değer, sıralama, eksen ölçeği ve yazımlar. Sayılar ABACUS'tandır (chart-format).
import { formatCompact, formatMoney, formatMoneyCompact, formatNumber } from "../lib/chart-format";

export interface RaceItem { key: string; label: string; /** Aynı gruptaki çubuklar aynı renkte; en çok dört grup renk alır. */ group?: string; /** Her dönemdeki değer (dönem sırasıyla); eksik değer sıfır sayılır. */ values: number[] }
export interface RacePeriod { key: string; label: string }
export type RaceKind = "count" | "money";

const at = (values: number[], index: number) => values[index] ?? 0;

/** Zaman `t` (kesirli dönem sırası) için doğrusal ara değer. */
export function valueAt(values: number[], t: number): number {
  if (!values.length) return 0;
  const last = values.length - 1, clamped = Math.min(Math.max(t, 0), last), low = Math.floor(clamped), high = Math.min(low + 1, last);
  const share = clamped - low;
  return at(values, low) + (at(values, high) - at(values, low)) * share;
}

export interface RaceRow { key: string; label: string; group: string | undefined; value: number; rank: number }

/** Zaman `t` için tüm öğeleri sıralar; sıra 0'dan başlar. Eşitlikte girdi sırası korunur. */
export function rowsAt(items: RaceItem[], t: number): RaceRow[] {
  return items
    .map((item, order) => ({ item, order, value: valueAt(item.values, t) }))
    .sort((a, b) => b.value - a.value || a.order - b.order)
    .map(({ item, value }, rank) => ({ key: item.key, label: item.label, group: item.group, value, rank }));
}

/** Eksen için "güzel" üst sınır: en büyük değeri aşan, 1-2-2,5-5 basamaklı en küçük değer. */
export function niceMax(max: number): number {
  if (!(max > 0)) return 1;
  const magnitude = 10 ** Math.floor(Math.log10(max));
  for (const factor of [1, 2, 2.5, 5, 10]) if (factor * magnitude >= max) return factor * magnitude;
  return 10 * magnitude;
}

/** Eksen çizgileri: en çok `count` adet, eşit aralıklı, 0 hariç. */
export function axisTicks(axisMax: number, count = 4): number[] {
  const step = niceMax(axisMax / count);
  const ticks: number[] = [];
  for (let value = step; value <= axisMax * 1.0001 && ticks.length < count + 2; value += step) ticks.push(value);
  return ticks;
}

/** Zaman `t` için eksenin hedef üst sınırı: en çok görünen N çubuğun en büyüğü. */
export function axisTarget(items: RaceItem[], t: number, topN: number): number {
  const rows = rowsAt(items, t).slice(0, topN);
  return niceMax(rows[0]?.value ?? 0);
}

export const fullText = (kind: RaceKind, value: number) => kind === "money" ? formatMoney(Math.round(value), 0) : formatNumber(Math.round(value), 0);
/** Çubuk ucundaki kısa yazım: ara değerler yuvarlanır, ekranda kuruş görünmez. */
export const shortText = (kind: RaceKind, value: number) => kind === "money" ? formatMoneyCompact(Math.round(value)) : formatCompact(Math.round(value));

/** Ekran okuyucu: "Ahmet Yıldız, 2. sıra, ₺1.250.000". */
export const rankAnnouncement = (kind: RaceKind, label: string, rank: number, value: number) => `${label}, ${rank + 1}. sıra, ${fullText(kind, value)}`;
/** Dönem duyurusu: "Ekim 2026, lider Marmara". */
export const periodAnnouncement = (period: string, leader: string) => `${period}, lider ${leader}`;

.figure { display: grid; min-width: 0; gap: var(--space-4); margin: 0; color: var(--foreground); --on-bar: var(--neutral-0); }
:global([data-theme="dark"]) .figure { --on-bar: var(--neutral-11); }
.head { min-width: 0; }
.title { font-family: var(--font-display); font-size: var(--text-lg); font-weight: 500; letter-spacing: var(--tracking-display); }
.description { margin: 2px 0 0; color: var(--text-secondary); font-size: var(--text-sm); }
.focus { display: grid; gap: var(--space-3); outline: none; border-radius: var(--radius-control); }
.focus:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: var(--focus-outline-offset, 2px); }
.field { position: relative; isolation: isolate; margin-top: var(--space-5); overflow: hidden; }
.axis { position: absolute; inset: 0 0 0 7.5rem; pointer-events: none; }
.tick { position: absolute; top: -1.25rem; bottom: 0; border-left: 1px solid var(--border); }
.tickText { position: absolute; top: 0; left: 4px; color: var(--text-muted); font-size: var(--text-xs); white-space: nowrap; font-variant-numeric: tabular-nums; }
.row { position: absolute; top: 4px; right: 0; left: 0; display: grid; grid-template-columns: 7.5rem minmax(0, 1fr); align-items: center; transition: transform var(--duration-considered) var(--ease-standard), opacity var(--duration-standard) var(--ease-standard); }
.row[data-hidden] { opacity: 0; }
.name { overflow: hidden; padding-right: var(--space-3); color: var(--text-secondary); font-size: var(--text-sm); text-align: right; text-overflow: ellipsis; white-space: nowrap; }
.row[data-lead] .name, .row[data-cursor] .name { color: var(--foreground); font-weight: 500; }
.track { position: relative; display: block; height: calc(100% - 8px); }
.bar { position: absolute; top: 0; bottom: 0; left: 0; min-width: 2px; border-radius: 0 var(--radius-control) var(--radius-control) 0; opacity: .9; }
.row[data-cursor] .bar { outline: 2px solid var(--foreground); outline-offset: 1px; }
.value { position: absolute; top: 50%; padding-left: var(--space-2); transform: translateY(-50%); font-size: var(--text-sm); font-variant-numeric: tabular-nums; white-space: nowrap; }
.row[data-lead] .value { font-weight: 600; }
.period { position: absolute; right: 0; bottom: 0; z-index: -1; color: var(--text-muted); font-family: var(--font-display); font-size: var(--text-4xl); letter-spacing: var(--tracking-display); line-height: 1; opacity: .35; animation: swap var(--duration-standard) var(--ease-enter); }
@keyframes swap { from { opacity: 0; filter: blur(4px); transform: translateY(.15em); } to { opacity: .35; filter: none; transform: none; } }
.legend { display: flex; flex-wrap: wrap; gap: var(--space-1) var(--space-4); margin: 0; padding: 0; list-style: none; color: var(--text-secondary); font-size: var(--text-sm); }
.legend li { display: inline-flex; align-items: center; gap: var(--space-2); }
.swatch { width: .75rem; height: .75rem; border-radius: 3px; }
.timeline { display: grid; grid-template-columns: auto auto minmax(0, 1fr) auto; align-items: center; gap: var(--space-3); }
.play { display: inline-flex; min-height: var(--control-height-sm); align-items: center; gap: var(--space-2); padding: 0 var(--space-3); border: 1px solid var(--border-strong); border-radius: var(--radius-control); background: var(--surface); color: var(--foreground); font: inherit; font-size: var(--text-sm); cursor: pointer; }
.play:hover { background: var(--surface-muted); }
.play:focus-visible, .slider:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: var(--focus-outline-offset, 2px); }
.edge { color: var(--text-muted); font-size: var(--text-xs); white-space: nowrap; }
.slider { width: 100%; min-height: var(--control-height-sm); accent-color: var(--accent); cursor: pointer; }
.empty { margin: 0; padding: var(--space-8) 0; color: var(--text-muted); text-align: center; }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.figure[data-narrow] .row { grid-template-columns: minmax(0, 1fr); }
.figure[data-narrow] .axis { left: 0; }
.figure[data-narrow] .name { position: absolute; z-index: 1; left: var(--space-2); max-width: 55%; padding: 0; color: var(--on-bar); text-align: left; text-shadow: 0 0 2px var(--accent-strong); }
.figure[data-narrow] .period { font-size: var(--text-2xl); }
.figure[data-reduced] .row, .figure[data-reduced] .period { transition: none; animation: none; }
@media (prefers-reduced-motion: reduce) { .row { transition: none; } .period { animation: none; } }

"use client";

import { useEffect, useId, useMemo, useRef, useState, type ChangeEvent, type KeyboardEvent } from "react";
import { clamp, seriesColor, useElementWidth, useOnScreen, useReducedMotionSafe } from "../lib/viz-utils";
import { axisTarget, axisTicks, fullText, periodAnnouncement, rankAnnouncement, rowsAt, shortText, type RaceItem, type RaceKind, type RacePeriod } from "./race-bar-chart-format";
import styles from "./race-bar-chart.module.css";

export type { RaceItem, RaceKind, RacePeriod };

/** Bir sıralamanın zaman içinde nasıl değiştiğini anlatmak için kullanın (yıl sonu özeti, lansman anlatısı); her gün bakılan panelde yeri yoktur, anlık karşılaştırma için çubuk grafik daha doğrudur. */
export interface RaceBarChartProps {
  periods: RacePeriod[];
  items: RaceItem[];
  /** Grafiğin adı, örneğin "Bölgeye göre aylık ciro". */
  label: string;
  description?: string;
  kind?: RaceKind;
  /** Aynı anda görünen çubuk sayısı. */
  topN?: number;
  /** Görününce kendiliğinden oynar ("hareketi azalt" açıkken oynamaz). */
  autoPlay?: boolean;
  /** Son dönemden sonra başa sarar. */
  loop?: boolean;
  /** Bir dönemin akış süresi (ms). */
  msPerPeriod?: number;
  emptyText?: string;
}

const ROW = 36;

export function RaceBarChart({ periods, items, label, description, kind = "money", topN = 8, autoPlay = true, loop = false, msPerPeriod = 1100, emptyText = "Veri yok." }: RaceBarChartProps) {
  const reduced = useReducedMotionSafe();
  const titleId = useId();
  const [box, width] = useElementWidth<HTMLDivElement>();
  const [visibleRef, onScreen] = useOnScreen<HTMLElement>();
  const lastIndex = Math.max(periods.length - 1, 0);
  const shown = Math.min(topN, items.length);
  const [clock, setClock] = useState(() => ({ t: 0, axis: axisTarget(items, 0, shown) }));
  const [playing, setPlaying] = useState(false);
  const [seek, setSeek] = useState(0);
  const [cursor, setCursor] = useState<number | null>(null);
  const [announce, setAnnounce] = useState("");
  const clockRef = useRef(clock);
  clockRef.current = clock;
  const started = useRef(false);

  // Görününce bir kez kendiliğinden başlar.
  useEffect(() => {
    if (started.current || !autoPlay || reduced || !onScreen || periods.length < 2) return;
    started.current = true;
    setPlaying(true);
  }, [autoPlay, onScreen, periods.length, reduced]);

  // Zaman ve eksen döngüsü: oynarken zamanı ilerletir, eksen üst sınırı hedefe yumuşakça yaklaşır. Duruncaya kadar kare çağırır.
  useEffect(() => {
    if (reduced || periods.length < 2) return;
    let raf = 0, previous = performance.now();
    const step = (now: number) => {
      const dt = Math.min(64, now - previous);
      previous = now;
      const current = clockRef.current;
      let t = current.t, stop = false;
      if (playing && onScreen) {
        t += dt / msPerPeriod;
        if (t >= lastIndex) {
          if (loop) t = 0; else { t = lastIndex; stop = true; }
        }
      }
      const target = axisTarget(items, t, shown);
      let axis = current.axis + (target - current.axis) * (1 - Math.exp(-dt / 220));
      const settled = Math.abs(axis - target) < target * .002;
      if (settled) axis = target;
      if (t !== current.t || axis !== current.axis) { clockRef.current = { t, axis }; setClock({ t, axis }); }
      if (stop) setPlaying(false);
      if (!stop && ((playing && onScreen) || !settled)) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [items, loop, lastIndex, msPerPeriod, onScreen, periods.length, playing, reduced, seek, shown]);

  const jump = (t: number) => {
    const next = clamp(reduced ? Math.round(t) : t, 0, lastIndex);
    const axis = reduced ? axisTarget(items, next, shown) : clockRef.current.axis;
    clockRef.current = { t: next, axis };
    setClock({ t: next, axis });
    setSeek(count => count + 1);
  };
  const settledAnnounce = (t: number) => {
    const index = Math.round(t), leader = rowsAt(items, index)[0];
    if (leader && periods[index]) setAnnounce(periodAnnouncement(periods[index]!.label, leader.label));
  };
  const toggle = () => {
    if (playing) { setPlaying(false); settledAnnounce(clock.t); return; }
    if (clock.t >= lastIndex) jump(0);
    setPlaying(true);
  };

  const groups = useMemo(() => [...new Set(items.map(item => item.group).filter((group): group is string => !!group))].slice(0, 4), [items]);
  const colorOf = (group: string | undefined) => seriesColor(group ? Math.max(0, groups.indexOf(group)) : 0);
  const rows = rowsAt(items, clock.t);
  const periodLabel = periods[Math.round(clock.t)]?.label ?? "";
  const narrow = width > 0 && width < 400;
  const ticks = axisTicks(clock.axis);

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.target !== event.currentTarget) return;
    const whole = Math.round(clock.t);
    if (event.key === " " || event.key === "Enter") { event.preventDefault(); toggle(); }
    else if (event.key === "ArrowRight") { event.preventDefault(); setPlaying(false); jump(whole + 1); settledAnnounce(whole + 1); }
    else if (event.key === "ArrowLeft") { event.preventDefault(); setPlaying(false); jump(whole - 1); settledAnnounce(whole - 1); }
    else if (event.key === "Home") { event.preventDefault(); setPlaying(false); jump(0); settledAnnounce(0); }
    else if (event.key === "End") { event.preventDefault(); setPlaying(false); jump(lastIndex); settledAnnounce(lastIndex); }
    else if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      const next = clamp((cursor ?? (event.key === "ArrowDown" ? -1 : shown)) + (event.key === "ArrowDown" ? 1 : -1), 0, shown - 1);
      setCursor(next);
      const row = rows[next];
      if (row) setAnnounce(rankAnnouncement(kind, row.label, row.rank, row.value));
    } else if (event.key === "Escape") { setCursor(null); setAnnounce(""); }
  };
  const onSlide = (event: ChangeEvent<HTMLInputElement>) => { setPlaying(false); jump(Number(event.target.value)); };

  if (!periods.length || !items.length) return <figure className={styles.figure}><figcaption className={styles.title}>{label}</figcaption><p className={styles.empty}>{emptyText}</p></figure>;

  return <figure ref={visibleRef} className={styles.figure} data-reduced={reduced || undefined} data-narrow={narrow || undefined} aria-labelledby={titleId}>
    <div className={styles.head}>
      <figcaption id={titleId} className={styles.title}>{label}</figcaption>
      {description && <p className={styles.description}>{description}</p>}
    </div>
    <div className={styles.focus} role="group" aria-roledescription="sıralama yarışı" aria-label={`${label}; boşluk oynatır ve duraklatır, sol ve sağ ok dönemi değiştirir, yukarı ve aşağı ok sırada gezinir`} tabIndex={0} onKeyDown={onKeyDown} onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget)) setCursor(null); }}>
      <div ref={box} className={styles.field} style={{ height: shown * ROW + 8 }} aria-hidden="true">
        <div className={styles.axis}>{ticks.map(tick => <span key={tick} className={styles.tick} style={{ left: `${(tick / clock.axis) * 100}%` }}><span className={styles.tickText}>{shortText(kind, tick)}</span></span>)}</div>
        {rows.map(row => {
          const visible = row.rank < shown;
          const percent = clamp((row.value / clock.axis) * 100, 0, 100);
          return <div key={row.key} className={styles.row} data-hidden={!visible || undefined} data-cursor={cursor === row.rank || undefined} data-lead={row.rank === 0 || undefined} style={{ transform: `translateY(${(visible ? row.rank : shown) * ROW}px)`, height: ROW }}>
            <span className={styles.name}>{row.label}</span>
            <span className={styles.track}>
              <span className={styles.bar} style={{ width: `${percent}%`, background: colorOf(row.group) }} />
              <span className={styles.value} style={{ left: `${percent}%` }}>{shortText(kind, row.value)}</span>
            </span>
          </div>;
        })}
        <span key={periodLabel} className={styles.period}>{periodLabel}</span>
      </div>
      {groups.length > 0 && <ul className={styles.legend} aria-hidden="true">{groups.map(group => <li key={group}><span className={styles.swatch} style={{ background: colorOf(group) }} />{group}</li>)}</ul>}
      <div className={styles.timeline}>
        <button type="button" className={styles.play} onClick={toggle} aria-label={playing ? "Duraklat" : clock.t >= lastIndex ? "Baştan oynat" : "Oynat"} aria-pressed={playing}>
          <span aria-hidden="true">{playing ? "❚❚" : "▶"}</span><span>{playing ? "Duraklat" : clock.t >= lastIndex ? "Baştan oynat" : "Oynat"}</span>
        </button>
        <span className={styles.edge}>{periods[0]?.label}</span>
        <input className={styles.slider} type="range" min={0} max={lastIndex} step="any" value={clock.t} onChange={onSlide} aria-label="Dönem" aria-valuetext={periodLabel} />
        <span className={styles.edge}>{periods[lastIndex]?.label}</span>
      </div>
    </div>
    <div className={styles.srOnly}><table>
      <caption>{label}</caption>
      <thead><tr><th scope="col">Öğe</th>{periods.map(period => <th key={period.key} scope="col">{period.label}</th>)}</tr></thead>
      <tbody>{items.map(item => <tr key={item.key}><th scope="row">{item.label}</th>{periods.map((period, index) => <td key={period.key}>{fullText(kind, item.values[index] ?? 0)}</td>)}</tr>)}</tbody>
    </table></div>
    <p className={styles.srOnly} aria-live="polite" aria-atomic="true">{announce}</p>
  </figure>;
}

export default RaceBarChart;
